// src/js/App.js
import React, { useState, useEffect } from "react";
import Login from "../jsx/Login";
import Register from "../jsx/Register";
import Contacts from "../jsx/Contacts";
import PrivateChat from "../jsx/PrivateChat";
import GroupChat from "../jsx/GroupChat";
import CreateGroup from "../jsx/CreateGroup";
import { auth } from "./firebaseConfig";
import { onAuthStateChanged, signOut } from "firebase/auth";

function App() {

    const [user, setUser] = useState(null);

    // ---------- CONTROLE DE TELAS ----------
    const [screen, setScreen] = useState("login");
    // login | register | contacts | private | group | createGroup

    const [chatUser, setChatUser] = useState(null);
    const [chatGroup, setChatGroup] = useState(null);

    // ---------- AUTENTICAÇÃO AUTOMÁTICA ----------
    useEffect(() => {
        const unsub = onAuthStateChanged(auth, (u) => {
            if (u) {
                setUser(u);
                setScreen("private"); // TELA PADRÃO
            } else {
                setUser(null);
                setScreen("login");
            }
        });
        return () => unsub();
    }, []);

    // ---------- LOGOUT ----------
    const logout = async () => {
        await signOut(auth);
        setUser(null);
        setScreen("login");
    };

    // ========== TELAS SEM LOGIN ==========
    if (!user) {
        if (screen === "register")
            return <Register setScreen={setScreen} />;

        return <Login setUser={setUser} setScreen={setScreen} />;
    }

    // ========== TELAS COM LOGIN ==========

    // Chat privado
    if (screen === "private") {

        // se não há usuário selecionado → vai para lista
        if (!chatUser) {
            return (
                <Contacts
                    currentUser={user}
                    setChatUser={setChatUser}
                    setChatGroup={setChatGroup}
                    setScreen={setScreen}
                    logout={logout}
                />
            );
        }

        return (
            <PrivateChat
                currentUser={user}
                otherUser={chatUser}
                onClose={() => setScreen("contacts")}
            />
        );
    }

    // Chat de grupo
    if (screen === "group") {
        return (
            <GroupChat
                currentUser={user}
                group={chatGroup}
                onClose={() => setScreen("contacts")}
            />
        );
    }
    // Tela de criação de grupo
    if (screen === "createGroup") {
        return (
            <CreateGroup
                currentUser={user}
                setScreen={setScreen}
            />
        );
    }

    // Tela principal de contatos
    if (screen === "contacts") {
        return (
            <Contacts
                currentUser={user}
                setChatUser={setChatUser}
                setChatGroup={setChatGroup}
                setScreen={setScreen}
                logout={logout}
            />
        );
    }

    return <div>Erro: Tela não encontrada.</div>;
}

export default App;
